import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.CvydjLy7.js";const k=JSON.parse('{"title":"11.9 从“能跑”到“能在生产上跑”","description":"","frontmatter":{"title":"11.9 从“能跑”到“能在生产上跑”"},"headers":[{"level":3,"title":"配置不要烤进镜像","slug":"配置不要烤进镜像","link":"#配置不要烤进镜像","children":[]},{"level":3,"title":"内存参数：容器感知默认是开的","slug":"内存参数-容器感知默认是开的","link":"#内存参数-容器感知默认是开的","children":[]},{"level":3,"title":"优雅停机","slug":"优雅停机","link":"#优雅停机","children":[]},{"level":3,"title":"日志走标准输出","slug":"日志走标准输出","link":"#日志走标准输出","children":[]},{"level":3,"title":"密钥不进镜像","slug":"密钥不进镜像","link":"#密钥不进镜像","children":[]},{"level":3,"title":"时区","slug":"时区","link":"#时区","children":[]}],"relativePath":"ch11/09.md","filePath":"ch11/09.md","lastUpdated":1789497795000}'),n={name:"ch11/09.md"};function p(l,s,h,o,d,c){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="_11-9-从-能跑-到-能在生产上跑" tabindex="-1">11.9 从“能跑”到“能在生产上跑” <a class="header-anchor" href="#_11-9-从-能跑-到-能在生产上跑" aria-label="Permalink to &quot;11.9 从“能跑”到“能在生产上跑”&quot;">​</a></h1><p>镜像能起来只是最低要求。下面这些是上线前必须处理掉的。</p><h3 id="配置不要烤进镜像" tabindex="-1">配置不要烤进镜像 <a class="header-anchor" href="#配置不要烤进镜像" aria-label="Permalink to &quot;配置不要烤进镜像&quot;">​</a></h3><p>理想状态是<strong>同一份镜像可以部署到任何环境</strong>。把环境相关的配置写进镜像，就变成每个环境都要单独构建一次。</p><p>Spring Boot 的外部化配置让这件事很好做，因为环境变量会被规范化后匹配到配置项。官方给的反向规则是：点转下划线、去掉连字符、转大写。比如 <code>spring.main.log-startup-info</code> 对应 <code>SPRING_MAIN_LOGSTARTUPINFO</code>。实测这几种写法都能覆盖 <code>server.port</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无覆盖                                   -&gt; Tomcat started on port 8080</span></span>
<span class="line"><span>SERVER_PORT=9999                         -&gt; Tomcat started on port 9999</span></span>
<span class="line"><span>SERVER__PORT=9998                        -&gt; Tomcat started on port 9998</span></span>
<span class="line"><span>SPRING_PROFILES_ACTIVE=prod + 端口覆盖    -&gt; The following 1 profile is active: &quot;prod&quot;</span></span></code></pre></div><p>注意最后一行：环境变量能同时覆盖端口和激活 profile，镜像本身不用改任何东西。部署命令就是把这些值传进去：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SPRING_PROFILES_ACTIVE=prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SPRING_DATASOURCE_URL=jdbc:mysql://db:3306/activity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    activity-server:1.0.0</span></span></code></pre></div><p>第 3 篇讲过配置的优先级顺序，环境变量排在命令行参数之后、<code>application-{profile}.yml</code> 之前，正好适合放“部署时才知道”的值。</p><h3 id="内存参数-容器感知默认是开的" tabindex="-1">内存参数：容器感知默认是开的 <a class="header-anchor" href="#内存参数-容器感知默认是开的" aria-label="Permalink to &quot;内存参数：容器感知默认是开的&quot;">​</a></h3><p>Java 10 之后 JVM 默认开启容器感知。实测一个限制 512MB 的容器：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker run --rm --memory=512m --entrypoint java activity-server:layered \\</span></span>
<span class="line"><span>      -XX:+PrintFlagsFinal -version</span></span>
<span class="line"><span>   size_t MaxHeapSize              = 134217728    {product} {ergonomic}   # 128 MB</span></span>
<span class="line"><span>     bool UseContainerSupport      = true         {product} {default}</span></span></code></pre></div><p><code>MaxHeapSize</code> 是 128MB，正好是 512MB 的 25%——这就是 <code>MaxRAMPercentage</code> 的默认值。堆之外还有元空间、线程栈、直接内存、JIT 代码缓存要占地方，25% 对多数应用偏保守。</p><p>调整不用改 Dockerfile，<code>JAVA_TOOL_OPTIONS</code> 这个环境变量 JVM 自己会读：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --memory=512m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JAVA_TOOL_OPTIONS=&quot;-XX:MaxRAMPercentage=75&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Picked up JAVA_TOOL_OPTIONS: -XX:MaxRAMPercentage=75</span></span>
<span class="line"><span>   size_t MaxHeapSize              = 402653184    {product} {ergonomic}   # 384 MB</span></span></code></pre></div><p><code>Picked up JAVA_TOOL_OPTIONS</code> 这行会打在标准错误上，它不是报错，只是提示。</p><p>反过来也要留意：<strong>如果容器没有设置内存上限，<code>MaxRAMPercentage</code> 会按宿主机内存算</strong>，可能开出一个远超预期的大堆。给容器设内存上限本身就是必要的。</p><h3 id="优雅停机" tabindex="-1">优雅停机 <a class="header-anchor" href="#优雅停机" aria-label="Permalink to &quot;优雅停机&quot;">​</a></h3><p>容器停止时运行时发的是 SIGTERM，应用需要在收到信号后停止接收新请求、把正在处理的请求做完。这个开关第 4 篇配过，容器场景下是必需品：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  shutdown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">graceful</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  lifecycle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    timeout-per-shutdown-phase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">20s</span></span></code></pre></div><p>生效时日志里能看到这段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Commencing graceful shutdown. Waiting for active requests to complete</span></span>
<span class="line"><span>Graceful shutdown complete</span></span></code></pre></div><p><code>timeout-per-shutdown-phase</code> 是兜底——等待超过这个时间就强制退出，避免一个卡住的请求把停机流程拖住。</p><h3 id="日志走标准输出" tabindex="-1">日志走标准输出 <a class="header-anchor" href="#日志走标准输出" aria-label="Permalink to &quot;日志走标准输出&quot;">​</a></h3><p>容器里的日志应该走 stdout/stderr，由容器运行时收集。Spring Boot 默认就是 console 输出，不需要配。</p><p>两条注意：</p><p><code>logging.file.name</code> 不要配。镜像层是只读的，写在容器文件系统里的日志随容器销毁一起消失，容器运行时也收集不到。</p><p>日志级别可以用环境变量调（<code>LOGGING_LEVEL_COM_EXAMPLE_RESOURCEHUB=DEBUG</code>），第 10 篇讲的 <code>loggers</code> 端点则能在不重启的情况下改，两者配合足够应付线上的排查需求。</p><h3 id="密钥不进镜像" tabindex="-1">密钥不进镜像 <a class="header-anchor" href="#密钥不进镜像" aria-label="Permalink to &quot;密钥不进镜像&quot;">​</a></h3><p>镜像会被推到仓库、会被拉下来、会被别人用 <code>docker history</code> 逐层看到。写在 Dockerfile 的 <code>ENV</code> 里的东西不是秘密——<strong><code>ENV</code> 的内容会进入镜像元数据</strong>。</p><p>密钥通过 <code>-e</code>、<code>--env-file</code> 传，或者挂载密钥文件、接入密钥管理服务。这一条没有例外。</p><h3 id="时区" tabindex="-1">时区 <a class="header-anchor" href="#时区" aria-label="Permalink to &quot;时区&quot;">​</a></h3><p>容器默认时区是 UTC。业务里有日期格式化、或者需要日志时间和业务时间对齐时，显式指定：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TZ=Asia/Shanghai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span></code></pre></div><hr>`,36)])])}const g=a(n,[["render",p]]);export{k as __pageData,g as default};
